import csv
import io

FIELDS = ['customer_id', 'long_identifier', 'note_state', 'note_value', 'ordinary_text']


def parse(raw):
    if not isinstance(raw, bytes):
        raise ValueError('UTF-8 CSV bytes required')
    rows = list(csv.reader(io.StringIO(raw.decode('utf-8-sig'), newline=''), strict=True))
    if not rows or rows[0] != FIELDS or any(len(row) != len(FIELDS) for row in rows):
        raise ValueError('fixed field dictionary and five columns required')
    return rows


def serialize(rows):
    stream = io.StringIO(newline='')
    csv.writer(stream, quoting=csv.QUOTE_ALL, lineterminator='\r\n').writerows(rows)
    return stream.getvalue().encode('utf8')


def encode(records):
    rows = [FIELDS]
    for record in records:
        if set(record) - {'customer_id', 'long_identifier', 'note', 'ordinary_text'}:
            raise ValueError('unknown field')
        for field in ('customer_id', 'long_identifier', 'ordinary_text'):
            if not isinstance(record.get(field), str):
                raise ValueError('identifiers and ordinary text are strings')
        state = 'missing' if 'note' not in record else 'null' if record['note'] is None else 'value'
        value = record.get('note') if state == 'value' else ''
        if not isinstance(value, str):
            raise ValueError('note is a string, null, or absent')
        rows.append([record['customer_id'], record['long_identifier'], state, value, record['ordinary_text']])
    return serialize(rows)


def decode(raw):
    records = []
    for customer, identifier, state, value, ordinary in parse(raw)[1:]:
        if state not in ('value', 'null', 'missing') or state != 'value' and value:
            raise ValueError('explicit, unambiguous note state required')
        record = dict(customer_id=customer, long_identifier=identifier, ordinary_text=ordinary)
        if state != 'missing':
            record['note'] = value if state == 'value' else None
        records.append(record)
    return records


def protect(raw):
    rows = parse(raw)
    return serialize([rows[0]] + [["'" + value for value in row] for row in rows[1:]])


def restore(raw):
    rows = parse(raw)
    if any(not value.startswith("'") for row in rows[1:] for value in row):
        raise ValueError('protected display cells must retain their prefix')
    return serialize([rows[0]] + [[value[1:] for value in row] for row in rows[1:]])


