import hashlib
import csv_codec


def decide(original, returned, *, display=False):
    before = csv_codec.parse(original)
    actual = csv_codec.parse(csv_codec.restore(returned) if display else returned)
    differences = []
    for row in range(max(len(before), len(actual))):
        for column, field in enumerate(csv_codec.FIELDS):
            expected = before[row][column] if row < len(before) else None
            observed = actual[row][column] if row < len(actual) else None
            if expected != observed:
                differences.append(dict(row=row, field=field, expected=expected, actual=observed))
    return dict(allow_writeback=not differences,
                original_sha256=hashlib.sha256(original).hexdigest(),
                returned_sha256=hashlib.sha256(returned).hexdigest(),
                differences=differences)

